    if(record.kind==='CANCELLATION'&&record.status==='RECORDED')cancelled+=amount;
    if(record.kind==='REFUND'){
      if(record.status==='VERIFIED'){validateRefundProof(record.verification?.proof,record);returned+=amount;}
