import {buildServicePeriodExample} from './stellar/scf-starforge-20261009/merchant-settlement-accounting/customer-statements/examples/service-period.mjs';
import {mkdir,writeFile} from 'node:fs/promises';
const result=buildServicePeriodExample(),p=result.document.servicePeriod;
if(p.totals.newCalls!==3||p.totals.consumedUnits!=='15'||p.totals.releasedUnits!=='15'||p.totals.admittedUnits!=='20'||p.totals.resultRecoveries!==1)throw new Error('Period movement differed from native sample outcomes');
if(p.calls.find(c=>c.requestId==='result-awaited').consumedUnits!=='0')throw new Error('Recovered result consumed allowance again');
if(p.totals.carriedReservations!==1||p.closing.unitsUsed!=='30'||p.closing.unitsReserved!=='10'||p.closing.unitsRemaining!=='60')throw new Error('Closing native balances differed');
if(!result.files['period.csv'].includes('"-5"'))throw new Error('Signed unit movement was lost in CSV');
const directory='./customer-period-example';await mkdir(directory,{mode:0o700,recursive:true});
for(const [name,body]of Object.entries(result.files))await writeFile(directory+'/'+name,body,{mode:0o600});
process.stdout.write(JSON.stringify({node:process.version,summary:result.summary,files:result.files}));
